CREATE TYPE "CustomerType" AS ENUM ('CF','NIT');
CREATE TYPE "SaleStatus" AS ENUM ('DRAFT','PENDING_PAYMENT','PAID','FEL_PENDING','FEL_CERTIFIED','FEL_REJECTED','CANCELLED');
CREATE TYPE "PaymentMethod" AS ENUM ('CASH','CARD','TRANSFER');
CREATE TYPE "InventoryMovementType" AS ENUM ('SALE','PURCHASE','ADJUSTMENT','RETURN','INITIAL_STOCK');
CREATE TYPE "PrintStatus" AS ENUM ('QUEUED','PRINTED','FAILED');
CREATE TABLE "User"("id" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "User_pkey" PRIMARY KEY("id"));
CREATE TABLE "Role"("id" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Role_pkey" PRIMARY KEY("id"));
CREATE TABLE "Permission"("id" TEXT NOT NULL,"key" TEXT NOT NULL,"description" TEXT NOT NULL,CONSTRAINT "Permission_pkey" PRIMARY KEY("id"));
CREATE TABLE "UserRole"("userId" TEXT NOT NULL,"roleId" TEXT NOT NULL,CONSTRAINT "UserRole_pkey" PRIMARY KEY("userId","roleId"));
CREATE TABLE "RolePermission"("roleId" TEXT NOT NULL,"permissionId" TEXT NOT NULL,CONSTRAINT "RolePermission_pkey" PRIMARY KEY("roleId","permissionId"));
CREATE TABLE "RefreshToken"("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"tokenHash" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"revokedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "RefreshToken_pkey" PRIMARY KEY("id"));
CREATE TABLE "Category"("id" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Category_pkey" PRIMARY KEY("id"));
CREATE TABLE "Product"("id" TEXT NOT NULL,"sku" TEXT NOT NULL,"barcode" TEXT,"name" TEXT NOT NULL,"description" TEXT,"salePrice" DECIMAL(12,2) NOT NULL,"cost" DECIMAL(12,2) NOT NULL,"stock" INTEGER NOT NULL DEFAULT 0,"minStock" INTEGER NOT NULL DEFAULT 0,"imageUrl" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"categoryId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Product_pkey" PRIMARY KEY("id"));
CREATE TABLE "Customer"("id" TEXT NOT NULL,"customerType" "CustomerType" NOT NULL,"name" TEXT NOT NULL,"nit" TEXT,"phone" TEXT,"email" TEXT,"address" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Customer_pkey" PRIMARY KEY("id"));
CREATE TABLE "Sale"("id" TEXT NOT NULL,"customerId" TEXT NOT NULL,"userId" TEXT NOT NULL,"subtotal" DECIMAL(12,2) NOT NULL,"discount" DECIMAL(12,2) NOT NULL,"tax" DECIMAL(12,2) NOT NULL,"total" DECIMAL(12,2) NOT NULL,"status" "SaleStatus" NOT NULL DEFAULT 'PAID',"felUuid" TEXT,"felSeries" TEXT,"felNumber" TEXT,"felCertifiedAt" TIMESTAMP(3),"felError" TEXT,"demoKey" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Sale_pkey" PRIMARY KEY("id"));
CREATE TABLE "SaleItem"("id" TEXT NOT NULL,"saleId" TEXT NOT NULL,"productId" TEXT NOT NULL,"productName" TEXT NOT NULL,"quantity" INTEGER NOT NULL,"unitPrice" DECIMAL(12,2) NOT NULL,"discount" DECIMAL(12,2) NOT NULL,"tax" DECIMAL(12,2) NOT NULL,"total" DECIMAL(12,2) NOT NULL,CONSTRAINT "SaleItem_pkey" PRIMARY KEY("id"));
CREATE TABLE "Payment"("id" TEXT NOT NULL,"saleId" TEXT NOT NULL,"method" "PaymentMethod" NOT NULL,"amount" DECIMAL(12,2) NOT NULL,"reference" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Payment_pkey" PRIMARY KEY("id"));
CREATE TABLE "InventoryMovement"("id" TEXT NOT NULL,"productId" TEXT NOT NULL,"userId" TEXT NOT NULL,"type" "InventoryMovementType" NOT NULL,"quantity" INTEGER NOT NULL,"previousStock" INTEGER NOT NULL,"newStock" INTEGER NOT NULL,"reason" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "InventoryMovement_pkey" PRIMARY KEY("id"));
CREATE TABLE "PrintJob"("id" TEXT NOT NULL,"saleId" TEXT NOT NULL,"printerName" TEXT,"status" "PrintStatus" NOT NULL DEFAULT 'QUEUED',"payload" JSONB NOT NULL,"printedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PrintJob_pkey" PRIMARY KEY("id"));
CREATE TABLE "AuditLog"("id" TEXT NOT NULL,"userId" TEXT,"action" TEXT NOT NULL,"entity" TEXT NOT NULL,"entityId" TEXT,"oldValues" JSONB,"newValues" JSONB,"ipAddress" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"saleId" TEXT,CONSTRAINT "AuditLog_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE UNIQUE INDEX "Role_name_key" ON "Role"("name"); CREATE UNIQUE INDEX "Permission_key_key" ON "Permission"("key"); CREATE UNIQUE INDEX "RefreshToken_tokenHash_key" ON "RefreshToken"("tokenHash"); CREATE UNIQUE INDEX "Category_name_key" ON "Category"("name"); CREATE UNIQUE INDEX "Product_sku_key" ON "Product"("sku"); CREATE UNIQUE INDEX "Product_barcode_key" ON "Product"("barcode"); CREATE UNIQUE INDEX "Customer_nit_key" ON "Customer"("nit"); CREATE UNIQUE INDEX "Sale_demoKey_key" ON "Sale"("demoKey");
ALTER TABLE "UserRole" ADD CONSTRAINT "UserRole_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "UserRole" ADD CONSTRAINT "UserRole_roleId_fkey" FOREIGN KEY("roleId") REFERENCES "Role"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "RolePermission" ADD CONSTRAINT "RolePermission_roleId_fkey" FOREIGN KEY("roleId") REFERENCES "Role"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "RolePermission" ADD CONSTRAINT "RolePermission_permissionId_fkey" FOREIGN KEY("permissionId") REFERENCES "Permission"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "RefreshToken" ADD CONSTRAINT "RefreshToken_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Product" ADD CONSTRAINT "Product_categoryId_fkey" FOREIGN KEY("categoryId") REFERENCES "Category"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Sale" ADD CONSTRAINT "Sale_customerId_fkey" FOREIGN KEY("customerId") REFERENCES "Customer"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Sale" ADD CONSTRAINT "Sale_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SaleItem" ADD CONSTRAINT "SaleItem_saleId_fkey" FOREIGN KEY("saleId") REFERENCES "Sale"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "SaleItem" ADD CONSTRAINT "SaleItem_productId_fkey" FOREIGN KEY("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Payment" ADD CONSTRAINT "Payment_saleId_fkey" FOREIGN KEY("saleId") REFERENCES "Sale"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "InventoryMovement" ADD CONSTRAINT "InventoryMovement_productId_fkey" FOREIGN KEY("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "InventoryMovement" ADD CONSTRAINT "InventoryMovement_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "PrintJob" ADD CONSTRAINT "PrintJob_saleId_fkey" FOREIGN KEY("saleId") REFERENCES "Sale"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_saleId_fkey" FOREIGN KEY("saleId") REFERENCES "Sale"("id") ON DELETE SET NULL ON UPDATE CASCADE;
